package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.formatLongOctalOrBinaryBytes.
 * Designed to maximize branch and line coverage.
 */
public class TarUtils_formatLongOctalOrBinaryBytes_TriageGen2Test {

    // Constants based on TarConstants logic implied in the code snippet
    // Since TarConstants is not provided, we assume standard TAR behavior:
    // UIDLEN is typically 8, MAXID is 07777777777 (octal), MAXSIZE is 07777777777 (octal)
    // For the sake of logic testing, we will treat them as values that trigger different paths.
    private static final int UIDLEN = 8;
    private static final long MAXID = 07777777777L;
    private static final long MAXSIZE = 07777777777L;

    @Test
    public void testFormatLongOctalOrBinaryBytes_PositiveSmallValue_OctalPath() {
        // Case: value >= 0 and value <= maxAsOctalChar
        // This should trigger formatLongOctalBytes
        long value = 123L;
        byte[] buf = new byte[11];
        int offset = 0;
        int length = UIDLEN;

        int result = TarUtils.formatLongOctalOrBinaryBytes(value, buf, offset, length);

        // Verification: length is UIDLEN, offset is 0, so result should be 8 (assuming formatLongOctalBytes works)
        Assert.assertEquals(offset + length, result);
    }

    @Test
    public void testFormatLongOctalOrBinaryBytes_PositiveLargeValue_BinaryPath_LengthLessThan9() {
        // Case: value > maxAsOctalChar AND length < 9
        // This triggers formatLongBinary AND formatBigIntegerBinary
        long value = MAXID + 1;
        byte[] buf = new byte[11];
        int offset = 0;
        int length = 8; // length < 9

        int result = TarUtils.formatLongOctalOrBinaryBytes(value, buf, offset, length);

        Assert.assertEquals(offset + length, result);
        // Check the sign bit for positive: buf[offset] should be 0x80
        Assert.assertEquals((byte) 0x80, buf[offset]);
    }

    @Test
    public void testFormatLongOctalOrBinaryBytes_PositiveLargeValue_BinaryPath_LengthGreaterEqual9() {
        // Case: value > maxAsOctalChar AND length >= 9
        // This triggers ONLY formatBigIntegerBinary
        long value = MAXSIZE + 1;
        byte[] buf = new byte[11];
        int offset = 0;
        int length = 10; // length >= 9

        int result = TarUtils.formatLongOctalOrBinaryBytes(value, buf, offset, length);

        Assert.assertEquals(offset + length, result);
        // Check the sign bit for positive: buf[offset] should be 0x80
        Assert.assertEquals((byte) 0x80, buf[offset]);
    }

    @Test
    public void testFormatLongOctalOrBinaryBytes_NegativeSmallValue_BinaryPath() {
        // Case: value < 0
        // Negative always goes to binary path regardless of maxAsOctalChar
        long value = -1L;
        byte[] buf = new byte[11];
        int offset = 0;
        int length = 8;

        int result = TarUtils.formatLongOctalOrBinaryBytes(value, buf, offset, length);

        Assert.assertEquals(offset + length, result);
        // Check the sign bit for negative: buf[offset] should be 0xff
        Assert.assertEquals((byte) 0xff, buf[offset]);
    }

    @Test
    public void testFormatLongOctalOrBinaryBytes_NegativeLargeValue_BinaryPath_LengthLessThan9() {
        // Case: value < 0 AND length < 9
        long value = -9999999999L;
        byte[] buf = new byte[11];
        int offset = 0;
        int length = 5;

        int result = TarUtils.formatLongOctalOrBinaryBytes(value, buf, offset, length);

        Assert.assertEquals(offset + length, result);
        Assert.assertEquals((byte) 0xff, buf[offset]);
    }

    @Test
    public void testFormatLongOctalOrBinaryBytes_NegativeLargeValue_BinaryPath_LengthGreaterEqual9() {
        // Case: value < 0 AND length >= 9
        long value = -9999999999L;
        byte[] buf = new byte[11];
        int offset = 0;
        int length = 10;

        int result = TarUtils.formatLongOctalOrBinaryBytes(value, buf, offset, length);

        Assert.assertEquals(offset + length, result);
        Assert.assertEquals((byte) 0xff, buf[offset]);
    }
}
